import{_ as t,o as a,c as o,i as s}from"./chunks/framework.DP1yFSuu.js";const m=JSON.parse('{"title":"Adoption Plan for Existing Applications","description":"","frontmatter":{},"headers":[],"relativePath":"guidance/adoption.md","filePath":"guidance/adoption.md"}'),n={name:"guidance/adoption.md"};function r(d,e,i,l,p,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adoption-plan-for-existing-applications" tabindex="-1">Adoption Plan for Existing Applications <a class="header-anchor" href="#adoption-plan-for-existing-applications" aria-label="Permalink to &quot;Adoption Plan for Existing Applications&quot;">​</a></h1><p>Cobalt is in alpha, so existing applications should adopt it in small, visible stages instead of planning a full UI replacement. The goal is to show progress now through tokens, baseline styles, and focused pilots while the design system expands component support, testing, and verification coverage.</p><p>This plan is for application teams that need a realistic path forward under delivery pressure.</p><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Use Cobalt in layers:</p><ol><li><strong>Tokens first.</strong> Adopt shared color, spacing, typography, radius, and focus decisions before replacing entire workflows.</li><li><strong>Baseline styles in scoped areas.</strong> Use <code>[data-co-base]</code> to progressively map native HTML elements to Cobalt typography and element defaults.</li><li><strong>Components only where ready.</strong> Replace components in small slices after checking docs, accessibility notes, wrappers, tests, and browser behavior.</li><li><strong>Roadmap the gaps.</strong> Keep local or legacy components where Cobalt does not yet support the pattern, and feed repeated blockers back into the roadmap.</li></ol><p>This mirrors patterns used by mature systems such as <a href="https://designsystem.digital.gov/maturity-model/" target="_blank" rel="noreferrer">USWDS</a>, <a href="https://atlassian.design/foundations/tokens/migrate-to-tokens/" target="_blank" rel="noreferrer">Atlassian</a>, <a href="https://carbondesignsystem.com/migrating/guide/overview/" target="_blank" rel="noreferrer">Carbon</a>, and <a href="https://polaris-react.shopify.com/version-guides/migrating-from-v11-to-v12" target="_blank" rel="noreferrer">Polaris</a>: adoption is incremental, measurable, and validated.</p><h2 id="adoption-stages" tabindex="-1">Adoption Stages <a class="header-anchor" href="#adoption-stages" aria-label="Permalink to &quot;Adoption Stages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What changes</th><th>Progress signal</th><th>Exit criteria</th></tr></thead><tbody><tr><td>0. Choose a slice</td><td>Pick one route, workflow, or page region.</td><td>A small target surface is named.</td><td>Current UI stack, key elements, risks, and unsupported patterns are known.</td></tr><tr><td>1. Add tokens</td><td>Install tokens and replace hard-coded values where safe.</td><td>The slice uses Cobalt token imports and semantic <code>--co-*</code> values.</td><td>Import order is verified and key styles use tokens instead of raw values.</td></tr><tr><td>2. Add baseline styles</td><td>Scope <code>@cobalt/tokens/css/base</code> with <code>[data-co-base]</code>.</td><td>Native headings, text, links, lists, tables, and code align locally.</td><td>The scoped area passes visual review and does not regress adjacent UI.</td></tr><tr><td>3. Pilot ready components</td><td>Replace a few low-risk, documented components.</td><td>A real workflow uses Cobalt tokens, baseline styles, and components.</td><td>Visual, accessibility, framework, browser, and regression checks pass.</td></tr><tr><td>4. Make Cobalt the new-work default</td><td>Use Cobalt for new UI where support is ready.</td><td>New features start from Cobalt decisions instead of cleanup later.</td><td>Team standards define when to use Cobalt, defer, or file a roadmap gap.</td></tr><tr><td>5. Expand and retire legacy</td><td>Move repeated patterns as Cobalt support matures.</td><td>Legacy CSS or component dependencies decline by route, bundle, or app.</td><td>Migrated slices no longer depend on old UI systems except intentional gaps.</td></tr></tbody></table><h2 id="readiness-checks" tabindex="-1">Readiness Checks <a class="header-anchor" href="#readiness-checks" aria-label="Permalink to &quot;Readiness Checks&quot;">​</a></h2><p>Before expanding beyond a pilot, confirm:</p><ul><li>token CSS loads once and in the correct order</li><li>baseline styles are scoped and visually reviewed</li><li>selected components have usable docs and acceptable <a href="/cobalt-design-system/components/status.html">Component Status</a></li><li>wrapper behavior works in the app framework</li><li>keyboard, focus, accessibility, browser, theme, and regression checks pass</li><li>unsupported patterns have a local fallback and a roadmap issue when repeated</li></ul><h2 id="what-to-show-management" tabindex="-1">What To Show Management <a class="header-anchor" href="#what-to-show-management" aria-label="Permalink to &quot;What To Show Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Evidence</th></tr></thead><tbody><tr><td>Foundation started</td><td>Tokens installed, import order verified, and one surface using semantic tokens.</td></tr><tr><td>Baseline adopted</td><td><code>[data-co-base]</code> applied to one scoped area and visually approved.</td></tr><tr><td>Pilot delivered</td><td>One real workflow uses Cobalt foundations and selected ready components.</td></tr><tr><td>Standard active</td><td>Team has a rule for when Cobalt is the default and when legacy remains in place.</td></tr><tr><td>Legacy reduced</td><td>Old styles or component dependencies are removed from migrated slices.</td></tr></tbody></table><p>The message is direct: Cobalt can make meaningful progress now, but broad adoption should wait for wider component coverage and stronger verification signals.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/cobalt-design-system/guidance/element-mapping.html">Element Mapping</a></li><li><a href="/cobalt-design-system/guidance/migration.html">Migrating an Existing Application</a></li><li><a href="/cobalt-design-system/components/status.html">Component Status</a></li><li><a href="/cobalt-design-system/tokens/structure.html">Token Structure</a></li></ul>',17)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
